diff --git a/src/share/ob_compatibility_security_feature_def.h b/src/share/ob_compatibility_security_feature_def.h
index f7df36703bd..92c95993d69 100644
--- a/src/share/ob_compatibility_security_feature_def.h
+++ b/src/share/ob_compatibility_security_feature_def.h
@@ -45,4 +45,9 @@ DEF_COMPAT_CONTROL_FEATURE(ORACLE_INSERT_ALL_PRIV_CHECK, "insert all privilege c
 DEF_COMPAT_CONTROL_FEATURE(MYSQL_SHOW_CREATE_PROCEDURE_PRIV_CHECK, "add show create procedure privilege check",
     MOCK_CLUSTER_VERSION_4_2_5_3, CLUSTER_VERSION_4_3_0_0,
     CLUSTER_VERSION_4_3_5_2)
+DEF_COMPAT_CONTROL_FEATURE(MYSQL_CTE_PRIV_CHECK, "add CTE privilege check",
+    MOCK_CLUSTER_VERSION_4_2_5_8, CLUSTER_VERSION_4_3_0_0,
+    MOCK_CLUSTER_VERSION_4_3_5_5, CLUSTER_VERSION_4_4_0_0,
+    MOCK_CLUSTER_VERSION_4_4_2_1, CLUSTER_VERSION_4_5_0_0,
+    CLUSTER_VERSION_4_6_0_0)
 #endif
diff --git a/src/sql/privilege_check/ob_privilege_check.cpp b/src/sql/privilege_check/ob_privilege_check.cpp
index 1e9da468147..43df30eb273 100644
--- a/src/sql/privilege_check/ob_privilege_check.cpp
+++ b/src/sql/privilege_check/ob_privilege_check.cpp
@@ -4049,6 +4049,31 @@ int ObPrivilegeCheck::get_stmt_ora_need_privs(
         //do nothing
       }
     }
+    // Check privilege for CTE definitions (WITH clause)
+    bool need_check_cte = false;
+    ObSessionPrivInfo session_priv;
+    if (OB_FAIL(ret)) {
+    } else if (OB_FAIL(ctx.session_info_->get_session_priv_info(session_priv))) {
+      LOG_WARN("failed to get session priv info", K(ret));
+    } else if (OB_FAIL(get_priv_need_check(session_priv, MYSQL_CTE_PRIV_CHECK, need_check_cte))) {
+      LOG_WARN("failed to get priv need check", K(ret));
+    } else if (need_check_cte) {
+      for (int64_t i = 0; OB_SUCC(ret) && i < dml_stmt->get_table_size(); ++i) {
+        const TableItem *table_item = dml_stmt->get_table_item(i);
+        if (OB_ISNULL(table_item)) {
+          ret = OB_ERR_UNEXPECTED;
+          LOG_WARN("table item is null", K(ret));
+        } else if (table_item->is_temp_table() && OB_NOT_NULL(table_item->ref_query_)) {
+          if (OB_FAIL(get_stmt_ora_need_privs(user_id,
+                                              ctx,
+                                              table_item->ref_query_,
+                                              need_privs,
+                                              check_flag))) {
+            LOG_WARN("Failed to extract priv info of CTE definition", K(i), K(dml_stmt), K(ret));
+          }
+        }
+      }
+    }
   }
   return ret;
 }
@@ -4086,6 +4111,26 @@ int ObPrivilegeCheck::get_stmt_need_privs(const ObSessionPrivInfo &session_priv,
         //do nothing
       }
     }
+    // Check privilege for CTE definitions (WITH clause)
+    bool need_check_cte = false;
+    if (OB_FAIL(ret)) {
+    } else if (OB_FAIL(get_priv_need_check(session_priv,
+                                     ObCompatFeatureType::MYSQL_CTE_PRIV_CHECK,
+                                     need_check_cte))) {
+      LOG_WARN("failed to get priv need check", K(ret));
+    } else if (need_check_cte) {
+      for (int64_t i = 0; OB_SUCC(ret) && i < dml_stmt->get_table_size(); ++i) {
+        const TableItem *table_item = dml_stmt->get_table_item(i);
+        if (OB_ISNULL(table_item)) {
+          ret = OB_ERR_UNEXPECTED;
+          LOG_WARN("table item is null", K(ret));
+        } else if (table_item->is_temp_table() && OB_NOT_NULL(table_item->ref_query_)) {
+          if (OB_FAIL(get_stmt_need_privs(session_priv, table_item->ref_query_, need_privs))) {
+            LOG_WARN("Failed to extract priv info of CTE definition", K(i), K(dml_stmt), K(ret));
+          }
+        }
+      }
+    }
   }
   return ret;
 }
